import React, { useState } from 'react';
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Drawer,
  Avatar,
  Box,
  Typography,
  Chip,
  IconButton,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Badge,
  Button,
  Checkbox,
} from '@mui/material';
import { styled } from '@mui/material/styles';
import { Group } from './types';
import { groups } from './data/mockData';
import CloseIcon from '@mui/icons-material/Close';
import HomeIcon from '@mui/icons-material/Home';
import InboxIcon from '@mui/icons-material/Inbox';
import AssistantIcon from '@mui/icons-material/Assistant';
import SearchIcon from '@mui/icons-material/Search';
import GroupIcon from '@mui/icons-material/Group';
import AutomationIcon from '@mui/icons-material/AutoFixHigh';
import CalendarIcon from '@mui/icons-material/CalendarToday';
import AnalyticsIcon from '@mui/icons-material/Analytics';
import TimeIcon from '@mui/icons-material/AccessTime';
import PayrollIcon from '@mui/icons-material/Payment';
import RecruitingIcon from '@mui/icons-material/PersonAdd';
import PerformanceIcon from '@mui/icons-material/TrendingUp';
import TrainingIcon from '@mui/icons-material/School';
import CompensationIcon from '@mui/icons-material/AttachMoney';
import WhistleblowingIcon from '@mui/icons-material/Campaign';
import SurveysIcon from '@mui/icons-material/Poll';
import MarketplaceIcon from '@mui/icons-material/Store';
import ImportIcon from '@mui/icons-material/Download';
import SettingsIcon from '@mui/icons-material/Settings';
import HelpIcon from '@mui/icons-material/Help';
import SortIcon from '@mui/icons-material/Sort';
import FilterListIcon from '@mui/icons-material/FilterList';
import AddIcon from '@mui/icons-material/Add';
import MinimizeIcon from '@mui/icons-material/Minimize';
import OpenInFullIcon from '@mui/icons-material/OpenInFull';

const LayoutRoot = styled(Box)({
  display: 'flex',
  height: '100vh',
  backgroundColor: '#F5F5F5',
});

const Sidebar = styled(Box)(({ theme }) => ({
  width: 280,
  backgroundColor: '#fff',
  borderRight: '1px solid rgba(0, 0, 0, 0.12)',
  display: 'flex',
  flexDirection: 'column',
}));

const MainContent = styled(Box)({
  flex: 1,
  display: 'flex',
  flexDirection: 'column',
  overflow: 'hidden',
  backgroundColor: '#F5F5F5',
});

const Header = styled(Box)(({ theme }) => ({
  height: 64,
  backgroundColor: '#fff',
  display: 'flex',
  alignItems: 'center',
  padding: '0 24px',
  borderBottom: '1px solid rgba(0, 0, 0, 0.12)',
}));

const Content = styled(Box)(({ theme }) => ({
  flex: 1,
  padding: '24px',
  backgroundColor: '#F5F5F5',
  overflow: 'auto',
}));

const StyledTableRow = styled(TableRow)(({ theme }) => ({
  '&:hover': {
    backgroundColor: 'rgba(0, 0, 0, 0.04)',
    cursor: 'pointer',
  },
}));

const StyledTableCell = styled(TableCell)(({ theme }) => ({
  padding: '12px 16px',
  borderBottom: '1px solid rgba(0, 0, 0, 0.12)',
  '&.MuiTableCell-head': {
    backgroundColor: '#fff',
    fontWeight: 600,
    color: 'rgba(0, 0, 0, 0.87)',
  },
}));

const UsageChip = styled(Chip)<{ type: string }>(({ theme, type }) => ({
  backgroundColor: 
    type === 'Permission Sets' ? '#FFF3DC' :
    type === 'Workflows' ? '#E8F5E9' :
    type === 'Access roles' ? '#FFF3DC' :
    '#F3E5F5',
  color:
    type === 'Permission Sets' ? '#975A16' :
    type === 'Workflows' ? '#1B5E20' :
    type === 'Access roles' ? '#975A16' :
    '#6A1B9A',
  borderRadius: '4px',
  height: '24px',
  fontWeight: 500,
  fontSize: '13px',
  marginRight: '8px',
}));

const ActionButton = styled(Button)(({ theme }) => ({
  textTransform: 'none',
  padding: '6px 12px',
  borderRadius: '6px',
  fontSize: '14px',
  fontWeight: 500,
  '&.MuiButton-outlined': {
    borderColor: 'rgba(0, 0, 0, 0.12)',
    color: 'rgba(0, 0, 0, 0.87)',
  },
  '&.MuiButton-contained': {
    backgroundColor: '#2196F3',
    color: '#fff',
    '&:hover': {
      backgroundColor: '#1976D2',
    },
  },
}));

const StyledListItem = styled(ListItem)(({ theme }) => ({
  padding: '8px 16px',
  height: 40,
  '&:hover': {
    backgroundColor: 'rgba(0, 0, 0, 0.04)',
    cursor: 'pointer',
  },
  '& .MuiListItemIcon-root': {
    minWidth: 40,
    color: 'rgba(0, 0, 0, 0.54)',
  },
  '& .MuiListItemText-root': {
    '& .MuiTypography-root': {
      fontSize: '14px',
      fontWeight: 400,
    },
  },
}));

const menuItems = [
  { icon: <HomeIcon />, text: 'Home' },
  { icon: <InboxIcon />, text: 'Inbox', badge: 6 },
  { icon: <AssistantIcon />, text: 'Assistant' },
  { icon: <SearchIcon />, text: 'Search' },
  { icon: <GroupIcon />, text: 'Organization' },
  { icon: <AutomationIcon />, text: 'Automations' },
  { icon: <CalendarIcon />, text: 'Calendars' },
  { icon: <AnalyticsIcon />, text: 'Analytics' },
  { icon: <TimeIcon />, text: 'Time Tracking' },
  { icon: <PayrollIcon />, text: 'Payroll' },
  { icon: <RecruitingIcon />, text: 'Recruiting' },
  { icon: <PerformanceIcon />, text: 'Performance & Development' },
  { icon: <TrainingIcon />, text: 'Training' },
  { icon: <CompensationIcon />, text: 'Compensation' },
  { icon: <WhistleblowingIcon />, text: 'Whistleblowing' },
  { icon: <SurveysIcon />, text: 'Surveys' },
  { icon: <MarketplaceIcon />, text: 'Marketplace' },
  { icon: <ImportIcon />, text: 'Imports' },
  { icon: <SettingsIcon />, text: 'Settings' },
  { icon: <HelpIcon />, text: 'Help' },
];

const App: React.FC = () => {
  const [selectedGroup, setSelectedGroup] = useState<Group | null>(null);

  const handleRowClick = (group: Group) => {
    setSelectedGroup(group);
  };

  const handleDrawerClose = () => {
    setSelectedGroup(null);
  };

  return (
    <LayoutRoot>
      <Sidebar>
        <Box sx={{ p: '16px', borderBottom: '1px solid rgba(0, 0, 0, 0.12)' }}>
          <Typography
            variant="h6"
            component="div"
            sx={{
              fontSize: '20px',
              fontWeight: 600,
              color: 'rgba(0, 0, 0, 0.87)',
            }}
          >
            Kolhorn
          </Typography>
        </Box>
        <List sx={{ flex: 1, pt: 0 }}>
          {menuItems.map((item) => (
            <StyledListItem key={item.text}>
              <ListItemIcon>
                {item.badge ? (
                  <Badge
                    badgeContent={item.badge}
                    color="primary"
                    sx={{
                      '& .MuiBadge-badge': {
                        backgroundColor: '#2196F3',
                        fontSize: '11px',
                        height: '16px',
                        minWidth: '16px',
                      },
                    }}
                  >
                    {item.icon}
                  </Badge>
                ) : (
                  item.icon
                )}
              </ListItemIcon>
              <ListItemText primary={item.text} />
            </StyledListItem>
          ))}
        </List>
      </Sidebar>

      <MainContent>
        <Header>
          <Typography
            variant="h6"
            sx={{
              fontSize: '20px',
              fontWeight: 600,
              color: 'rgba(0, 0, 0, 0.87)',
            }}
          >
            Groups
          </Typography>
          <Box sx={{ flex: 1 }} />
          <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
            <ActionButton
              variant="outlined"
              startIcon={<SortIcon />}
              size="small"
            >
              Sort
            </ActionButton>
            <ActionButton
              variant="outlined"
              startIcon={<FilterListIcon />}
              size="small"
            >
              Filter
            </ActionButton>
            <ActionButton
              variant="contained"
              startIcon={<AddIcon />}
              size="small"
            >
              Create group
            </ActionButton>
            <IconButton size="small">
              <MinimizeIcon />
            </IconButton>
            <IconButton size="small">
              <OpenInFullIcon />
            </IconButton>
            <IconButton size="small">
              <CloseIcon />
            </IconButton>
          </Box>
        </Header>

        <Content>
          <TableContainer
            component={Paper}
            sx={{
              boxShadow: 'none',
              border: '1px solid rgba(0, 0, 0, 0.12)',
              borderRadius: '8px',
            }}
          >
            <Table>
              <TableHead>
                <TableRow>
                  <StyledTableCell padding="checkbox">
                    <Checkbox size="small" />
                  </StyledTableCell>
                  <StyledTableCell>Name</StyledTableCell>
                  <StyledTableCell align="center"># Members</StyledTableCell>
                  <StyledTableCell>Usage</StyledTableCell>
                  <StyledTableCell>Owner</StyledTableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {groups.map((group) => (
                  <StyledTableRow key={group.id} onClick={() => handleRowClick(group)}>
                    <StyledTableCell padding="checkbox">
                      <Checkbox size="small" />
                    </StyledTableCell>
                    <StyledTableCell>{group.name}</StyledTableCell>
                    <StyledTableCell align="center">{group.members.length}</StyledTableCell>
                    <StyledTableCell>
                      {group.usage.map((type, index) => (
                        <UsageChip
                          key={index}
                          label={type}
                          type={type}
                        />
                      ))}
                    </StyledTableCell>
                    <StyledTableCell>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Avatar
                          src={group.owner.avatar}
                          sx={{
                            width: 24,
                            height: 24,
                          }}
                        />
                        <Typography
                          sx={{
                            fontSize: '14px',
                            color: 'rgba(0, 0, 0, 0.87)',
                          }}
                        >
                          {group.owner.name}
                        </Typography>
                      </Box>
                    </StyledTableCell>
                  </StyledTableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>

          <Drawer
            anchor="right"
            open={Boolean(selectedGroup)}
            onClose={handleDrawerClose}
            PaperProps={{
              sx: {
                width: '400px',
                backgroundColor: '#fff',
              },
            }}
          >
            {selectedGroup && (
              <>
                <Box
                  sx={{
                    p: '24px',
                    borderBottom: '1px solid rgba(0, 0, 0, 0.12)',
                  }}
                >
                  <Typography
                    variant="h6"
                    sx={{
                      fontSize: '20px',
                      fontWeight: 600,
                      color: 'rgba(0, 0, 0, 0.87)',
                      mb: 3,
                    }}
                  >
                    {selectedGroup.name}
                  </Typography>

                  <Typography
                    sx={{
                      fontSize: '14px',
                      color: 'rgba(0, 0, 0, 0.6)',
                      fontWeight: 500,
                      mb: 1,
                    }}
                  >
                    Owner
                  </Typography>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Avatar src={selectedGroup.owner.avatar} />
                    <Typography>{selectedGroup.owner.name}</Typography>
                  </Box>
                </Box>

                <Box sx={{ p: '24px' }}>
                  <Typography
                    sx={{
                      fontSize: '14px',
                      color: 'rgba(0, 0, 0, 0.6)',
                      fontWeight: 500,
                      mb: 2,
                    }}
                  >
                    Members are assigned based on the following conditions:
                  </Typography>

                  <Box sx={{ mb: 2 }}>
                    <Typography
                      sx={{
                        fontSize: '13px',
                        color: 'rgba(0, 0, 0, 0.6)',
                        mb: 1,
                      }}
                    >
                      Department
                    </Typography>
                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                      {selectedGroup.conditions.department.map((dept) => (
                        <Chip
                          key={dept}
                          label={dept}
                          size="small"
                          sx={{
                            backgroundColor: 'rgba(0, 0, 0, 0.08)',
                            color: 'rgba(0, 0, 0, 0.87)',
                            height: '24px',
                            fontSize: '13px',
                          }}
                        />
                      ))}
                    </Box>
                  </Box>

                  <Box>
                    <Typography
                      sx={{
                        fontSize: '13px',
                        color: 'rgba(0, 0, 0, 0.6)',
                        mb: 1,
                      }}
                    >
                      Position
                    </Typography>
                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                      {selectedGroup.conditions.position.map((pos) => (
                        <Chip
                          key={pos}
                          label={pos}
                          size="small"
                          sx={{
                            backgroundColor: 'rgba(0, 0, 0, 0.08)',
                            color: 'rgba(0, 0, 0, 0.87)',
                            height: '24px',
                            fontSize: '13px',
                          }}
                        />
                      ))}
                    </Box>
                  </Box>

                  <Box sx={{ mt: 3 }}>
                    <Typography
                      sx={{
                        fontSize: '14px',
                        color: 'rgba(0, 0, 0, 0.6)',
                        fontWeight: 500,
                        mb: 2,
                      }}
                    >
                      Members ({selectedGroup.members.length})
                    </Typography>
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                      {selectedGroup.members.slice(0, 5).map((_, index) => (
                        <Box
                          key={index}
                          sx={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: 2,
                          }}
                        >
                          <Avatar src={`https://i.pravatar.cc/150?img=${index + 20}`} />
                          <Box>
                            <Typography
                              sx={{
                                fontSize: '14px',
                                color: 'rgba(0, 0, 0, 0.87)',
                              }}
                            >
                              Member {index + 1}
                            </Typography>
                            <Typography
                              variant="body2"
                              sx={{
                                fontSize: '13px',
                                color: 'rgba(0, 0, 0, 0.6)',
                              }}
                            >
                              {selectedGroup.conditions.position[0]}
                            </Typography>
                          </Box>
                        </Box>
                      ))}
                    </Box>
                  </Box>
                </Box>
              </>
            )}
          </Drawer>
        </Content>
      </MainContent>
    </LayoutRoot>
  );
};

export default App;
